# mixlib.py -- ms-mixed (moonshot round, 14 Oct 2026).  Mixed targets at block 3: 1 kernel + 4 rank-2 in 10.
# Exact formal programs in C[G] (G generated by free monomials and dir(1)); group elements are exact 8x8
# Gaussian-dyadic matrices (hooklib.GM, copied from wave16/t514-search).  Two things live here:
#   (1) hook potentials (Theorem R in V (x) Lambda^4 V, f = 5) with PER-SLOT targets: K_t, gains, T2 = "every
#       generator maps (+)_l E_l into Y" where E_l = Y cap T_l^-1 Y  (E_K: 56, E_R: 136 for Y = N);
#   (2) an exact final solver: is T_w e_w in the left C[B]-span of the generators?  The coefficients delta are
#       searched on the closure of "matching" free letters b = h g^-1 (exact; complete for the closure only).
import sys, os, itertools, random
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import numpy as np
np.seterr(all='ignore')
from hooklib import *

D1, D2, D4 = gm_dir(1), gm_dir(2), gm_dir(4)
KK = D1 @ D2 @ D4
R12 = D1 @ D2
I0 = gm_eye()

# ------------------------------------------------------------------ free-letter membership -------------------------
def mono_data(g):
    """(perm, ph) with g[perm[x], x] = i^ph[x], or None if g is not a monomial with entries in {1,i,-1,-i}"""
    if g.s != 0: return None
    nz = (g.re != 0) | (g.im != 0)
    if not ((nz.sum(axis=0) == 1).all() and (nz.sum(axis=1) == 1).all()): return None
    perm, ph = [], []
    for x in range(8):
        r = int(np.nonzero(nz[:, x])[0][0])
        c = (int(g.re[r, x]), int(g.im[r, x]))
        if c not in ((1, 0), (0, 1), (-1, 0), (0, -1)): return None
        perm.append(r); ph.append([(1, 0), (0, 1), (-1, 0), (0, -1)].index(c))
    return perm, ph

def _mobius(phi):
    c = list(phi)
    for j in range(3):
        for x in range(8):
            if x >> j & 1: c[x] = (c[x] - c[x ^ (1 << j)]) % 4
    return c

def is_engine(g):
    d = mono_data(g)
    if d is None: return False
    perm, ph = d
    p0 = perm[0]
    for a in range(8):
        for b in range(8):
            if perm[a ^ b] ^ p0 != (perm[a] ^ p0) ^ (perm[b] ^ p0): return False
    c = _mobius(ph)
    for S in range(8):
        w = bin(S).count('1')
        if w == 2 and c[S] % 2: return False
        if w == 3 and c[S] % 4: return False
    return True

def is_widened(g):
    return mono_data(g) is not None

def rand_engine(rng):
    """uniform-ish random element of the engine free group B (affine perm, Z4-quadratic phase, global i^c)"""
    while True:
        A = [rng.randrange(8) for _ in range(3)]
        if len({A[0], A[1], A[2], A[0] ^ A[1], A[0] ^ A[2], A[1] ^ A[2], A[0] ^ A[1] ^ A[2]} - {0}) == 7: break
    c = rng.randrange(8)
    perm = []
    for x in range(8):
        y = c
        for j in range(3):
            if x >> j & 1: y ^= A[j]
        perm.append(y)
    a = [rng.randrange(4) for _ in range(3)]; b = [rng.randrange(2) for _ in range(3)]; c0 = rng.randrange(4)
    ph = []
    for x in range(8):
        xs = [(x >> j) & 1 for j in range(3)]
        v = c0 + sum(a[j] * xs[j] for j in range(3)) + 2 * (b[0] * xs[0] * xs[1] + b[1] * xs[0] * xs[2] + b[2] * xs[1] * xs[2])
        ph.append(v % 4)
    return gm_mono(perm, ph)

def rand_widened(rng):
    perm = list(range(8)); rng.shuffle(perm)
    return gm_mono(perm, [rng.randrange(4) for _ in range(8)])

# ------------------------------------------------------------------ formal generators -----------------------------
# a generator is {slot: {key: [coef (python int mod p or exact tuple), GM]}}; coefficients are kept mod p (search)
class Program:
    def __init__(self, W, p):
        self.W, self.p = W, p
        self.I = Field(p).I
        self.gens = [{l: {I0.key(): [1, I0]}} for l in range(W)]
        self.moves = []          # (L, items) as given

    def combo(self, items):
        """sum of coef * b * gen_j ; items = [(coef, b, j)]"""
        p = self.p
        new = {}
        for coef, b, j in items:
            for l, terms in self.gens[j].items():
                d = new.setdefault(l, {})
                for k, (c, g) in terms.items():
                    h = b @ g; kh = h.key()
                    if kh in d: d[kh][0] = (d[kh][0] + coef * c) % p
                    else: d[kh] = [(coef * c) % p, h]
        for l in list(new):
            new[l] = {k: v for k, v in new[l].items() if v[0] % p}
            if not new[l]: del new[l]
        return new

    def lmul(self, L, gen):
        return {l: {(L @ g).key(): [c, L @ g] for k, (c, g) in t.items()} for l, t in gen.items()}

    def move(self, L, items):
        c = self.combo(items)
        u = self.lmul(L, c)
        self.gens.append(u); self.moves.append((L, items))
        return u

    def nterms(self, j):
        return sum(len(t) for t in self.gens[j].values())

# ------------------------------------------------------------------ hook potentials with per-slot targets ---------
class Pot:
    """Theorem-R potential for Y in M = V (x) Lambda^4 V (Y = 'N' or 'Nperp'), W slots with targets Ts"""
    def __init__(self, H, Ts, Y='N'):
        self.H, self.F, self.W = H, H.F, len(Ts)
        inN = set(NIDX.tolist())
        self.Yi = NIDX if Y == 'N' else np.array([i for i in range(DM) if i not in inN])
        self.Oi = np.array([i for i in range(DM) if i not in set(self.Yi.tolist())])
        self.dY = len(self.Yi)
        self.Kb = np.eye(self.dY * self.W, dtype=np.float64)
        self.pot = 0
        self.E = []
        for T in Ts:
            RT = H.rho(T)
            Eb = self.F.nullspace(RT[np.ix_(self.Oi, self.Yi)])
            self.E.append(Eb.astype(np.float64))
        self.dem = [self.dY - e.shape[1] for e in self.E]

    def Rgen(self, gen, l):
        R = np.zeros((DM, self.dY))
        for k, (c, g) in gen.get(l, {}).items():
            R = R + (c % self.F.p) * self.H.rho(g)[:, self.Yi]
        return np.fmod(R, self.F.pf)

    def update(self, gen):
        """add the constraint of a new generator; return the gain"""
        out = np.zeros((DM, self.Kb.shape[1]))
        for l in gen:
            blk = self.Kb[l * self.dY:(l + 1) * self.dY]
            out = out + self.F.mm(self.Rgen(gen, l), blk)
        A = np.fmod(out, self.F.pf)[self.Oi]
        nul = self.F.nullspace(A)
        inc = self.Kb.shape[1] - nul.shape[1]
        self.Kb = np.fmod(self.F.mm(self.Kb, nul.astype(np.float64)), self.F.pf)
        self.pot += inc
        return inc

    def gain(self, gen):
        out = np.zeros((DM, self.Kb.shape[1]))
        for l in gen:
            blk = self.Kb[l * self.dY:(l + 1) * self.dY]
            out = out + self.F.mm(self.Rgen(gen, l), blk)
        A = np.fmod(out, self.F.pf)[self.Oi]
        return self.F.rank(A) if A.shape[1] else 0

    def t2(self, gen):
        for l in gen:
            R = self.Rgen(gen, l)
            if self.F.mm(R[self.Oi], self.E[l]).any(): return False
        return True

    def t2_defect(self, gen):
        tot = 0
        for l in gen:
            R = self.Rgen(gen, l)
            tot += self.F.rank(self.F.mm(R[self.Oi], self.E[l]))
        return tot

# ------------------------------------------------------------------ exact final solver -----------------------------
def modinv(a, p): return pow(int(a) % p, p - 2, p)

def solve_mod(A, b, p):
    """solve A x = b mod p (A: list of dict rows {col: val}, dense fallback). returns x (dict) or None"""
    import numpy as _np
    rows = len(A); cols = 1 + max([max(r) for r in A if r] + [-1])
    M = _np.zeros((rows, cols + 1), dtype=object)
    for i, r in enumerate(A):
        for c, v in r.items(): M[i, c] = v % p
        M[i, cols] = b[i] % p
    M = M.astype(_np.int64)
    piv = []; r = 0
    for c in range(cols):
        nz = _np.nonzero(M[r:, c])[0]
        if len(nz) == 0: continue
        pv = r + nz[0]
        if pv != r: M[[r, pv]] = M[[pv, r]]
        M[r] = (M[r] * modinv(M[r, c], p)) % p
        col = M[:, c].copy(); col[r] = 0
        nzr = _np.nonzero(col)[0]
        if len(nzr): M[nzr] = (M[nzr] - (col[nzr, None] * M[r][None, :]) % p) % p
        piv.append(c); r += 1
        if r == rows: break
    # consistency
    for i in range(r, rows):
        if M[i, cols] % p: return None
    x = {}
    for i, c in enumerate(piv): x[c] = int(M[i, cols])
    return x

def final_solve(prog, targets, member, maxb=4000, slots=None):
    """targets: {slot w: GM T}.  For each w, find delta_{w,i} in C[B] (B by `member`) with sum_i delta_i gen_i = T e_w.
    Closure of matching letters.  Returns dict w -> (ok, nunknowns, neq)."""
    p = prog.p
    res = {}
    gens = prog.gens
    # index of all terms: slot -> list of (i, key, coef, g)
    terms_by_slot = {}
    for i, gen in enumerate(gens):
        for l, t in gen.items():
            for k, (c, g) in t.items():
                terms_by_slot.setdefault(l, []).append((i, k, c, g))
    ginv_cache = {}
    def ginv(g):
        k = g.key()
        if k not in ginv_cache:
            ginv_cache[k] = GM(*_inv_exact(g))
        return ginv_cache[k]
    for w, T in targets.items():
        need = [(w, T.key(), T)]
        seen_h = {(w, T.key())}
        unknowns = {}           # (i, bkey) -> (idx, b)
        qi = 0
        while qi < len(need) and len(unknowns) < maxb:
            l, hk, h = need[qi]; qi += 1
            for (i, k, c, g) in terms_by_slot.get(l, []):
                b = h @ ginv(g)
                if not member(b): continue
                bk = b.key()
                if (i, bk) in unknowns: continue
                unknowns[(i, bk)] = (len(unknowns), b)
                # all terms of b * gen_i become equations
                for l2, t2 in gens[i].items():
                    for k2, (c2, g2) in t2.items():
                        h2 = b @ g2; key2 = (l2, h2.key())
                        if key2 not in seen_h:
                            seen_h.add(key2); need.append((l2, h2.key(), h2))
        # equations: for each (slot, h) coefficient
        eqs = {}
        for (i, bk), (idx, b) in unknowns.items():
            for l2, t2 in gens[i].items():
                for k2, (c2, g2) in t2.items():
                    key2 = (l2, (b @ g2).key())
                    eqs.setdefault(key2, {})
                    eqs[key2][idx] = (eqs[key2].get(idx, 0) + c2) % p
        keys = list(eqs.keys())
        if (w, T.key()) not in eqs: res[w] = (False, len(unknowns), len(keys)); continue
        A = [eqs[k] for k in keys]
        bvec = [1 if k == (w, T.key()) else 0 for k in keys]
        x = solve_mod(A, bvec, p)
        res[w] = (x is not None, len(unknowns), len(keys))
    return res

def _inv_exact(g):
    """exact inverse of a unitary Gaussian-dyadic matrix: conjugate transpose (all our elements are unitary)"""
    return (g.re.T.copy(), -g.im.T.copy(), 0) if g.s == 0 else _inv_dyadic(g)

def _inv_dyadic(g):
    # g = (re + i im)/2^s unitary => g^-1 = g^H = (re^T - i im^T)/2^s
    return (g.re.T.copy(), -g.im.T.copy(), g.s)
